/* Public source browsing never awards credit or changes a student's academic record. */
var TransferGuideCore=(()=>{
 const normalize=s=>String(s||'').toUpperCase().replace(/\s+/g,'');
 const terms={Winter:0,Spring:1,Summer:2,Autumn:3,Fall:3};
 function applicability(row,year,term){if(!year||!(term in terms))return 'Select the term you took the course to check the published range.';const value=+year*4+terms[term],start=row.effective?.start,end=row.effective?.end,ordinal=t=>t&&t.term in terms?+t.year*4+terms[t.term]:null,a=ordinal(start),b=ordinal(end);if(a!==null&&value<a)return 'Outside the published range: before the effective start.';if(b!==null&&(value>b||value===b&&row.effective.endInclusive===false))return 'Outside the published range: after the effective end.';if(a===null)return 'Effective start is unparsed or absent: official review required.';return 'Within the parsed published range; confirm current policy, campus and major applicability.'}
 function search(rows,f){const query=normalize(f.query);return rows.filter(r=>(!f.from||r.sourceInstitution===f.from)&&(!f.to||r.destinationInstitution===f.to)&&(!query||normalize([r.sourceRaw,r.destinationRaw,r.requirementsRaw].join(' ')).includes(query)))}
 return{applicability,search};
})();
let transferEvidencePromise,cascadiaEvidencePromise;
function publicSnapshot(path){return fetch(path).then(r=>{if(!r.ok)throw Error('This source snapshot is unavailable. Please try again.');return r.json()})}
function transferGuidePage(){return journeyPage(3,'Know what travels with you.',`<p class="journey-lede">Search the original published transfer statements, including course combinations, effective terms and campus conditions.</p><p>Credit equivalency and degree applicability are different decisions. These source records do not automatically award credit or satisfy a major requirement.</p><form id="transfer-guide-filter" class="degree-optimizer"><div class="form-grid"><label>Sending college<select name="from"><option value="">All sending colleges</option></select></label><label>Receiving university<select name="to"><option value="">All receiving universities</option></select></label><label>Course or phrase<input name="query" placeholder="PHYS& 114 or CSE 142" maxlength="100"></label><label>Course taken: year<input name="year" type="number" min="1980" max="2050" placeholder="2026"></label><label>Course taken: term<select name="term"><option value="">Choose term</option><option>Winter</option><option>Spring</option><option>Summer</option><option>Autumn</option></select></label></div><button class="btn primary">Find published mappings →</button></form><div id="transfer-guide-results" aria-live="polite"><p role="status">Opening source guides…</p></div><a class="journey-secondary" href="#source-library">All college sources →</a>`,'roadmap')}
async function bindTransferGuides(){const form=document.querySelector('#transfer-guide-filter');if(!form)return;try{if(!transferEvidencePromise)transferEvidencePromise=publicSnapshot('transfer-evidence.json').catch(e=>{transferEvidencePromise=null;throw e});const data=await transferEvidencePromise;if(!form.isConnected)return;for(const [name,key]of [['from','sourceInstitution'],['to','destinationInstitution']])form.elements[name].innerHTML+=[...new Set(data.records.map(r=>r[key]))].sort().map(s=>`<option>${esc(s)}</option>`).join('');let page=0;const draw=()=>{const f=Object.fromEntries(new FormData(form)),rows=TransferGuideCore.search(data.records,f),target=document.querySelector('#transfer-guide-results'),limit=20;target.innerHTML=`<p>${rows.length} matching source rows · Snapshot checked ${esc(data.checked)}. Showing ${rows.length? page*limit+1:0}–${Math.min((page+1)*limit,rows.length)}.</p>${rows.slice(page*limit,(page+1)*limit).map(r=>`<article class="degree-goal"><span class="eyebrow">${esc(r.sourceInstitution)} → ${esc(r.destinationInstitution)}</span><h3>${esc(r.sourceRaw)}</h3><p><strong>Published receiving credit:</strong> ${esc(r.destinationRaw||"No separate receiving entry; check the combined/reference row in the official table.")}</p>${r.requirementsRaw?`<p>Requirements: ${esc(r.requirementsRaw)}</p>`:''}<p>Effective statement: ${esc(r.effectiveRaw||'Not provided')}</p><p class="plan-trust-alert">${esc(TransferGuideCore.applicability(r,f.year,f.term))}</p>${r.obsolete?'<p>Historical / obsolete course record.</p>':''}${r.campusRestrictionsRaw?`<p>Campus restriction: ${esc(r.campusRestrictionsRaw)}</p>`:''}${r.sourceCampuses?.length?`<p>Sending campuses listed: ${r.sourceCampuses.map(esc).join(', ')}</p>`:''}${r.reviewReasons?.length?`<details><summary>Conditions that need review</summary><ul>${r.reviewReasons.map(t=>`<li>${esc(t)}</li>`).join('')}</ul></details>`:''}<p class="quiet-note">${esc(r.majorApplicability)}. Awarded credits are not calculated from this row.</p><a class="journey-secondary" href="${esc(r.source)}" target="_blank" rel="noopener">Original official table ↗</a></article>`).join('')||'<p>No exact source rows match. Try the source course code or use the official guide; no match does not establish that a course is nontransferable.</p>'}<div class="journey-actions"><button class="btn" id="transfer-prev" ${page===0?'disabled':''}>← Previous</button><button class="btn" id="transfer-next" ${(page+1)*limit>=rows.length?'disabled':''}>Next →</button></div><details><summary>Coverage and receiving-campus limits</summary>${(data.warnings||[]).map(s=>`<p>${esc(s)}</p>`).join('')}<p>UW Seattle guide rows are not automatically relabeled as UW Tacoma or UW Bothell equivalents. Exact campus-specific crosswalks appear separately.</p></details>`;target.querySelector('#transfer-prev').onclick=()=>{page--;draw()};target.querySelector('#transfer-next').onclick=()=>{page++;draw()}};form.onsubmit=e=>{e.preventDefault();page=0;draw()};draw()}catch(e){if(form.isConnected)document.querySelector('#transfer-guide-results').innerHTML=`<p role="alert">${esc(e.message)}</p>`}}
function collegeCatalogPage(){return journeyPage(3,'A first degree. A bigger horizon.',`<p class="journey-lede">Read all 29 degree and certificate pages in Cascadia’s reviewed 2026–27 catalog. Associate transfer degrees, applied degrees and certificates have different transfer rules.</p><label>Find a credential<input id="cascadia-search" placeholder="Associate, science, application development…" maxlength="100"></label><div id="cascadia-programs" class="degree-goals" aria-live="polite"><p role="status">Loading the published catalog…</p></div><section id="cascadia-reader" class="degree-optimizer" hidden></section><a class="journey-secondary" href="#programs">All program choices →</a>`,'degrees')}
async function bindCollegeCatalog(){const input=document.querySelector('#cascadia-search');if(!input)return;try{if(!cascadiaEvidencePromise)cascadiaEvidencePromise=publicSnapshot('cascadia-curricula.json').catch(e=>{cascadiaEvidencePromise=null;throw e});const rows=await cascadiaEvidencePromise;if(!input.isConnected)return;const draw=()=>{const list=document.querySelector('#cascadia-programs'),matches=rows.filter(r=>r.title.toLowerCase().includes(input.value.toLowerCase()));list.innerHTML=`<p>${matches.length} published credentials</p>`+matches.map(r=>`<article class="degree-goal"><span class="eyebrow">${esc(r.credential)}</span><h3>${esc(r.title)}</h3><button class="btn" data-cascadia-source="${esc(r.id)}">Read full published requirements →</button></article>`).join('');list.querySelectorAll('[data-cascadia-source]').forEach(b=>b.onclick=()=>{const r=rows.find(x=>x.id===b.dataset.cascadiaSource),target=document.querySelector('#cascadia-reader');target.hidden=false;target.innerHTML=`<span class="eyebrow">${esc(r.catalogYear)} · Checked ${esc(r.checked)}</span><h2>${esc(r.title)}</h2><a class="journey-secondary" href="${esc(r.url)}" target="_blank" rel="noopener">Official program catalog ↗</a><div class="uw-source-text" tabindex="0">${esc(r.text)}</div><p>Source text includes credit, residency and course-choice conditions. This is a source reader; it does not certify degree completion or transfer admission.</p><a class="btn primary" href="#degrees">Add or edit your associate-degree goal →</a>`;target.scrollIntoView({block:'start',behavior:state.reduceMotion?'auto':'smooth'})})};input.oninput=draw;draw()}catch(e){if(input.isConnected)document.querySelector('#cascadia-programs').innerHTML=`<p role="alert">${esc(e.message)}</p>`}}
function installEvidenceBrowser(){const oldBind=bind;bind=()=>{oldBind();bindTransferGuides();bindCollegeCatalog()};const oldSources=sources;sources=()=>oldSources()+`<section class="degree-optimizer"><h2>Expanded source coverage</h2><p>12,646 UW/WSU course records load by subject as needed. Reviewed course drafts preserve prerequisite choices, minimum grades and unresolved eligibility conditions.</p><div class="journey-actions"><a class="btn primary" href="#transfer-guides">Search 3,936 transfer statements →</a><a class="btn" href="#college-catalogs">Cascadia’s 29 published credentials →</a><a class="btn" href="#programs">UW and WSU source-based drafts →</a></div></section>`}
if(typeof module!=='undefined')module.exports=TransferGuideCore;
